import json, pathlib, sys, itertools, hashlib, datetime
root = pathlib.Path(sys.argv[1])
graph = json.loads((root/".dev-graph/state/graph.json").read_text(encoding="utf-8"))
leases = json.loads((root/".git/dev-graph/leases.json").read_text(encoding="utf-8"))["leases"]
rec = json.loads((root/"eval-log/run-dev-graph-schedule-execution.json").read_text(encoding="utf-8"))
nodes = {n["graph_node_id"]: n for n in graph["nodes"]}
fails = []

# --- independent scope overlap pairs from graph store ---
scope = {i: set(n.get("resource_scope") or []) for i, n in nodes.items()}
overlap_pairs = {frozenset((a,b)) for a,b in itertools.combinations(sorted(scope),2) if scope[a] & scope[b]}
print("independent overlap pairs:", [sorted(p) for p in overlap_pairs])
batches = rec["batches"]["tasks"]
for batch in batches:
    for a,b in itertools.combinations(batch,2):
        if frozenset((a,b)) in overlap_pairs:
            fails.append(f"OBS1: overlapping pair {a},{b} in same batch {batch}")
# also verify the overlapping pair is actually reported as conflict pair
cp = {frozenset((c["left"], c["right"])) for c in rec["conflict_pairs"] if c["kind"]=="ready_pair"}
for p in overlap_pairs:
    if len(p & set(rec["ready_set"]["tasks"])) == 2 and p not in cp:
        fails.append(f"OBS1: overlap pair {sorted(p)} not reported in conflict_pairs")
print("OBS1", "PASS" if not fails else fails)

# --- OBS2 blocked excluded + reason reported ---
def done(nid):
    n = nodes.get(nid)
    return bool(n) and (n.get("status")=="done" or (n.get("completion_evidence") or {}).get("status") in ("closed","done","completed"))
blocked = {i for i,n in nodes.items() if any(not done(d) for d in (n.get("depends_on") or []))}
print("independent blocked:", sorted(blocked))
f2=[]
for b in blocked:
    if b in rec["ready_set"]["tasks"]:
        f2.append(f"OBS2: blocked {b} in ready set")
    ent = [u for u in rec.get("unmapped",[]) if u.get("external_ref")==b]
    if not ent:
        f2.append(f"OBS2: no report entry for blocked {b}")
    else:
        e=ent[0]
        unmet = sorted(d for d in nodes[b]["depends_on"] if not done(d))
        if sorted(e.get("blocking_depends_on") or []) != unmet or not e.get("reason"):
            f2.append(f"OBS2: reason/blocking_depends_on mismatch for {b}: {e}")
print("OBS2", "PASS" if not f2 else f2); fails+=f2

# --- OBS3 lease active suppress / stale reclaim ---
now = datetime.datetime.now(datetime.timezone.utc)
f3=[]
for l in leases:
    exp = datetime.datetime.fromisoformat(l["expires_at"])
    nid = l["graph_node_id"]
    active = exp > now
    print(f"lease {nid} expires={exp} active={active} state={l['state']}")
    if active:
        if nid in rec["ready_set"]["tasks"]: f3.append(f"OBS3: active-lease {nid} present in ready set")
        if nid not in rec.get("conflicts",[]): f3.append(f"OBS3: active-lease {nid} not reported as conflict")
        if not any(c["kind"]=="lease" and c["left"]==nid for c in rec["conflict_pairs"]): f3.append(f"OBS3: no lease conflict_pair for {nid}")
    else:
        if nid not in rec["ready_set"]["tasks"]: f3.append(f"OBS3: stale-lease {nid} not reclaimed into ready set")
        if nid in rec.get("conflicts",[]): f3.append(f"OBS3: stale-lease {nid} wrongly treated as conflict")
print("OBS3", "PASS" if not f3 else f3); fails+=f3

# --- OBS4 batch size / uniqueness ---
f4=[]
if any(len(b)>2 for b in batches): f4.append(f"OBS4: batch exceeds max-parallel 2: {batches}")
flat=[t for b in batches for t in b]
if sorted(flat)!=sorted(rec["ready_set"]["tasks"]): f4.append(f"OBS4: batch membership != ready set: {flat} vs {rec['ready_set']['tasks']}")
if len(flat)!=len(set(flat)): f4.append("OBS4: duplicate task across batches")
hints=rec["assignment_hints"]
branches=[h["suggested_branch"] for h in hints]; claims=[h["claim_command"] for h in hints]; ids=[h["graph_node_id"] for h in hints]
if len(set(branches))!=len(branches): f4.append("OBS4: duplicate suggested_branch")
if len(set(claims))!=len(claims): f4.append("OBS4: duplicate claim command")
if sorted(ids)!=sorted(rec["ready_set"]["tasks"]): f4.append("OBS4: assignment_hints != ready set")
for h in hints:
    if h["suggested_branch"] != f"devgraph/{h['graph_node_id']}": f4.append(f"OBS4: bad branch {h}")
    if not h["claim_command"].startswith(f"/dev-graph worktree claim {h['graph_node_id']}"): f4.append(f"OBS4: bad claim command {h}")
print("OBS4", "PASS" if not f4 else f4); fails+=f4

# --- read-only / digest invariants ---
f5=[]
if rec["graph_sha256_before"]!=rec["graph_sha256_after"]: f5.append("digest: graph changed")
if rec["lease_sha256_before"]!=rec["lease_sha256_after"]: f5.append("digest: lease changed")
cur_graph = hashlib.sha256((root/".dev-graph/state/graph.json").read_bytes()).hexdigest()
cur_lease = hashlib.sha256((root/".git/dev-graph/leases.json").read_bytes()).hexdigest()
if cur_graph != rec["graph_sha256_after"]: f5.append(f"digest: graph on disk {cur_graph} != receipt {rec['graph_sha256_after']}")
if cur_lease != rec["lease_sha256_after"]: f5.append("digest: lease on disk differs from receipt")
if rec["lease_source"]!="git_common_dir": f5.append("lease source not git common dir")
if rec["ready_set"]["features"] or rec["batches"]["features"]: 
    if set(rec["ready_set"]["features"]) & set(rec["ready_set"]["tasks"]): f5.append("feature/task ready mixed")
print("DIGEST", "PASS" if not f5 else f5); fails+=f5
print("\nOVERALL:", "PASS" if not fails else "FAIL")
print(json.dumps(fails, ensure_ascii=False, indent=2))
